"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";

import { apiGet } from "@/lib/api";
import { formatMonth, formatNumber, formatPercent } from "@/lib/format";


type BranchOption = { region: string; branch_code: string; branch_name: string };
type TrendPoint = { month: string; quantity: number; line_count: number };
type PatternRow = {
  pattern_set: string; sku_name: string; size_code: string; base_sku_count: number;
  variant_count: number; active_variant_count: number; inactive_variant_count: number;
  status: string; first_observed_month: string; last_positive_sale_month: string | null;
  selling_branch_count: number; gross_quantity: number; revenue: number; line_count: number;
  quantity_per_line: number | null; revenue_per_line: number | null; growth: number | null;
  lifecycle: string; history_months: number | null; positive_months: number;
  adi: number | null; cv: number | null; demand_pattern: string; abc_class: string;
  contribution_pct: number | null; cumulative_pct: number | null; trend: TrendPoint[];
  inactive_variant_rate: number | null; previous_inactive_variant_rate: number | null;
  inactive_rate_change: number | null;
};
type RankingRow = Pick<PatternRow, "pattern_set" | "sku_name" | "gross_quantity" | "revenue" | "growth" | "abc_class" | "contribution_pct" | "cumulative_pct" | "inactive_variant_rate" | "previous_inactive_variant_rate" | "inactive_rate_change">;
type Metric = "quantity" | "revenue" | "growth";
type Overview = {
  data_as_of_month: string;
  filters: { region: string; branch: string; size_code: string; factory_sku: string; search: string; date_from: string; date_to: string; demand_pattern: string; abc_class: string; lifecycle: string };
  options: { regions: string[]; branches: BranchOption[]; size_codes: string[]; demand_patterns: string[]; abc_classes: string[]; lifecycles: string[] };
  thresholds: { adi: number; cv2: number; min_history_months: number; min_positive_months: number };
  methodology: { pattern_rollup: string; weight: string; dispersion: string; lifecycle: { new: string; growth: string; mature: string; decline: string }; inactive_alert: string };
  kpis: { pattern_count: number; gross_quantity: number; revenue: number; active_count: number; inactive_count: number; new_count: number; previous_new_count: number; inactive_alert_count: number; variant_count: number; inactive_variant_count: number };
  page: number; page_size: number; total: number; items: PatternRow[];
  ranking: { top: RankingRow[]; bottom: RankingRow[]; growth_top: RankingRow[]; growth_bottom: RankingRow[]; pareto: RankingRow[]; pareto_80_count: number };
  inactive_alerts: RankingRow[];
  sizes: Array<{ size_code: string; gross_quantity: number; revenue: number; growth: number | null }>;
  size_region: Array<{ size_code: string; region: string; gross_quantity: number; revenue: number; growth: number | null }>;
  pattern_region: Array<{ pattern_set: string; region: string; gross_quantity: number; revenue: number; growth: number | null; abc_class: string; contribution_pct: number | null; cumulative_pct: number | null }>;
};
type Variant = { bravo_sku: string; base_sku: string; factory_sku: string; sku_name: string; status: string; first_observed_month: string; last_positive_sale_month: string | null; gross_quantity: number; contribution_pct: number | null; variant_type: string; history_months: number | null; positive_months: number; negative_months: number; adi: number | null; cv2: number | null; demand_pattern: string };
type Detail = {
  pattern_set: string;
  filters: { date_from: string; date_to: string };
  thresholds: { adi: number; cv2: number };
  history: Array<{ month: string; quantity: number; revenue: number; line_count: number }>;
  variants: Variant[];
  distribution: Array<{ region: string; branch_code: string; branch_name: string; gross_quantity: number }>;
};

function isOverview(value: unknown): value is Overview {
  if (!value || typeof value !== "object") return false;
  const item = value as Partial<Overview>;
  return Boolean(item.filters && item.options && item.kpis && item.ranking && item.methodology && Array.isArray(item.items) && Array.isArray(item.sizes) && Array.isArray(item.inactive_alerts));
}

function money(value: number | null | undefined): string {
  if (value === null || value === undefined) return "—";
  return new Intl.NumberFormat("vi-VN", { style: "currency", currency: "VND", maximumFractionDigits: 0 }).format(value);
}
function number(value: number | null | undefined, digits = 2): string { return value === null || value === undefined ? "—" : formatNumber(value, digits); }
function growthClass(value: number | null) { return value === null ? "neutral" : value >= 0 ? "positive" : "negative"; }
function activeClass(value: string) { return value === "Hoạt động" ? "active" : "inactive"; }
function metricValue(row: { gross_quantity: number; revenue?: number; growth?: number | null }, metric: Metric) {
  return metric === "revenue" ? row.revenue ?? 0 : metric === "growth" ? row.growth ?? 0 : row.gross_quantity;
}
function metricLabel(value: number, metric: Metric) {
  return metric === "revenue" ? money(value) : metric === "growth" ? formatPercent(value) : formatNumber(value);
}

function downloadCsv(data: Overview) {
  const headers = ["pattern_set", "sku_name", "quantity", "revenue", "growth", "demand_pattern", "abc", "lifecycle", "variants", "active_variants", "inactive_rate", "inactive_rate_change", "adi", "cv2"];
  const rows = data.items.map((row) => [row.pattern_set, row.sku_name, row.gross_quantity, row.revenue, row.growth ?? "", row.demand_pattern, row.abc_class, row.lifecycle, row.variant_count, row.active_variant_count, row.inactive_variant_rate ?? "", row.inactive_rate_change ?? "", row.adi ?? "", row.cv === null ? "" : row.cv ** 2]);
  const csv = [headers, ...rows].map((row) => row.map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(",")).join("\r\n");
  const url = URL.createObjectURL(new Blob(["\uFEFF", csv], { type: "text/csv;charset=utf-8" }));
  const anchor = document.createElement("a"); anchor.href = url; anchor.download = `bo-mau-${data.filters.date_from.slice(0, 7)}-${data.filters.date_to.slice(0, 7)}.csv`; anchor.click(); URL.revokeObjectURL(url);
}

function Sparkline({ points }: { points: TrendPoint[] }) {
  const width = 128, height = 36, max = Math.max(...points.map((point) => point.quantity), 1);
  const path = points.map((point, index) => `${2 + index / Math.max(points.length - 1, 1) * (width - 4)},${height - 3 - point.quantity / max * (height - 6)}`).join(" ");
  return <svg className="ps-spark" viewBox={`0 0 ${width} ${height}`} role="img" aria-label="Xu hướng 12 tháng"><polyline points={path} fill="none" stroke="currentColor" strokeWidth="2.3" /></svg>;
}

function HistoryChart({ rows }: { rows: Detail["history"] }) {
  if (!rows.length) return <p className="ps-empty">Không có lịch sử.</p>;
  const width = 900, height = 220, max = Math.max(...rows.map((row) => row.quantity), 1);
  const path = rows.map((row, index) => `${16 + index / Math.max(rows.length - 1, 1) * (width - 32)},${height - 22 - row.quantity / max * (height - 42)}`).join(" ");
  return <div className="ps-history"><svg viewBox={`0 0 ${width} ${height}`}>{[.25,.5,.75].map((ratio) => <line key={`pattern-history-grid-${ratio}`} x1="16" x2={width - 16} y1={height * ratio} y2={height * ratio} />)}<polyline points={path} fill="none" stroke="#23afff" strokeWidth="3" /></svg><div><span>{formatMonth(rows[0].month)}</span><strong>Đỉnh {formatNumber(max)} M2</strong><span>{formatMonth(rows.at(-1)!.month)}</span></div></div>;
}

function Matrix({ rows, rowKey, rowLabel, metric }: { rows: Array<{ size_code?: string; pattern_set?: string; region: string; gross_quantity: number; revenue?: number; growth?: number | null; abc_class?: string }>; rowKey: "size_code" | "pattern_set"; rowLabel: string; metric: Metric }) {
  const rowValues = [...new Set(rows.map((row) => String(row[rowKey] ?? "")))];
  const regions = [...new Set(rows.map((row) => row.region))];
  const map = new Map(rows.map((row) => [`${String(row[rowKey])}\u0000${row.region}`, row]));
  const max = Math.max(...rows.map((row) => Math.abs(metricValue(row, metric))), 1);
  if (!rows.length) return <p className="ps-empty">Không có dữ liệu heatmap.</p>;
  return <div className="ps-matrix-scroll"><table className="ps-matrix"><thead><tr><th>{rowLabel}</th>{regions.map((region) => <th key={`matrix-header-${rowKey}-${region}`}>{region}</th>)}</tr></thead><tbody>{rowValues.map((value) => <tr key={`matrix-row-${rowKey}-${value}`}><th>{value}</th>{regions.map((region) => { const row = map.get(`${value}\u0000${region}`); const amount = row ? metricValue(row, metric) : 0; return <td key={`matrix-cell-${rowKey}-${value}-${region}`} className={metric === "growth" ? growthClass(row?.growth ?? null) : ""} style={{ background: `rgba(35,175,255,${.08 + Math.abs(amount) / max * .8})` }}>{row?.abc_class ? <b className={`abc abc-${row.abc_class.toLowerCase()}`}>{row.abc_class}</b> : null}{metricLabel(amount, metric)}</td>; })}</tr>)}</tbody></table></div>;
}

export function EdaPatternSet() {
  const [data, setData] = useState<Overview | null>(null);
  const [region, setRegion] = useState(""); const [branch, setBranch] = useState(""); const [sizeCode, setSizeCode] = useState("");
  const [factoryDraft, setFactoryDraft] = useState(""); const [factorySku, setFactorySku] = useState("");
  const [searchDraft, setSearchDraft] = useState(""); const [search, setSearch] = useState("");
  const [dateFrom, setDateFrom] = useState(""); const [dateTo, setDateTo] = useState("");
  const [demandPattern, setDemandPattern] = useState(""); const [abcClass, setAbcClass] = useState(""); const [lifecycle, setLifecycle] = useState("");
  const [page, setPage] = useState(1); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);
  const [detail, setDetail] = useState<Detail | null>(null); const [detailLoading, setDetailLoading] = useState(false);
  const [matrixMetric, setMatrixMetric] = useState<Metric>("quantity");
  const [rankingMetric, setRankingMetric] = useState<"demand" | "growth">("demand");

  useEffect(() => {
    let cancelled = false;
    apiGet<unknown>("/eda/pattern-set/overview", { region: region || undefined, branch: branch || undefined, size_code: sizeCode || undefined, factory_sku: factorySku || undefined, search: search || undefined, date_from: dateFrom || undefined, date_to: dateTo || undefined, demand_pattern: demandPattern || undefined, abc_class: abcClass || undefined, lifecycle: lifecycle || undefined, page, page_size: 50 })
      .then((response) => { if (cancelled) return; if (!isOverview(response)) throw new Error("API Bộ mẫu chưa được nạp. Hãy restart backend."); setData(response); setError(null); })
      .catch((reason: Error) => { if (!cancelled) setError(reason.message); })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [abcClass, branch, dateFrom, dateTo, demandPattern, factorySku, lifecycle, page, region, search, sizeCode]);

  const branches = useMemo(
    () => [...new Map(
      (data?.options.branches ?? [])
        .filter((item) => !region || item.region === region)
        .map((item) => [`${item.region}\u0000${item.branch_code}`, item]),
    ).values()],
    [data?.options.branches, region],
  );
  const pages = Math.max(1, Math.ceil((data?.total ?? 0) / 50));
  const newGrowth = data?.kpis.previous_new_count ? data.kpis.new_count / data.kpis.previous_new_count - 1 : null;

  function change(action: () => void) { setLoading(true); setPage(1); setDetail(null); action(); }
  function submit(event: FormEvent) { event.preventDefault(); change(() => { setFactorySku(factoryDraft.trim()); setSearch(searchDraft.trim()); }); }
  function openDetail(patternSet: string) { setDetailLoading(true); setDetail(null); apiGet<Detail>("/eda/pattern-set/detail", { pattern_set: patternSet, region: region || undefined, branch: branch || undefined, size_code: sizeCode || undefined, factory_sku: factorySku || undefined, date_from: dateFrom || data?.filters.date_from, date_to: dateTo || data?.filters.date_to }).then((response) => { setDetail(response); setError(null); }).catch((reason: Error) => setError(reason.message)).finally(() => setDetailLoading(false)); }

  const rankingTop = rankingMetric === "growth" ? data?.ranking.growth_top : data?.ranking.top;
  const rankingBottom = rankingMetric === "growth" ? data?.ranking.growth_bottom : data?.ranking.bottom;

  return <div className="ps-page">
    <div className="ps-heading"><div><p className="eyebrow">PATTERN SET</p><h3>EDA Bộ mẫu</h3><p>Aggregate trực tiếp toàn bộ base SKU và Bravo SKU thuộc cùng `pattern_set`.</p></div><div className="ps-heading-actions"><span>Dữ liệu đến {data?.data_as_of_month ? formatMonth(data.data_as_of_month) : "—"}</span><button disabled={!data} onClick={() => data && downloadCsv(data)}>Export CSV</button></div></div>
    <section className="ps-filters">
      <label>Region<select value={region} onChange={(event) => change(() => { setRegion(event.target.value); setBranch(""); })}><option value="">Tất cả vùng</option>{data?.options.regions.map((item) => <option key={`pattern-region-${item}`}>{item}</option>)}</select></label>
      <label>Branch<select value={branch} onChange={(event) => change(() => setBranch(event.target.value))}><option value="">Tất cả chi nhánh</option>{branches.map((item) => <option key={`pattern-branch-${item.region}-${item.branch_code}-${item.branch_name}`} value={item.branch_code}>{item.branch_code} — {item.branch_name}</option>)}</select></label>
      <label>Kích thước (price_group)<select value={sizeCode} onChange={(event) => change(() => setSizeCode(event.target.value))}><option value="">Tất cả kích thước</option>{data?.options.size_codes.map((item) => <option key={`pattern-size-${item}`} value={item}>{item}</option>)}</select></label>
      <form onSubmit={submit}><label>Mã mẫu nhà máy<input value={factoryDraft} onChange={(event) => setFactoryDraft(event.target.value)} placeholder="VD: FP948603" /></label><label>Pattern set / Tên SKU<input value={searchDraft} onChange={(event) => setSearchDraft(event.target.value)} placeholder="Tìm kiếm" /></label><button type="submit">Lọc</button></form>
      <label>Từ tháng<input type="date" value={dateFrom || data?.filters.date_from.slice(0,10) || ""} onChange={(event) => change(() => setDateFrom(event.target.value))} /></label><label>Đến tháng<input type="date" value={dateTo || data?.filters.date_to.slice(0,10) || ""} onChange={(event) => change(() => setDateTo(event.target.value))} /></label>
      <label>Demand<select value={demandPattern} onChange={(event) => change(() => setDemandPattern(event.target.value))}><option value="">Tất cả nhóm</option>{data?.options.demand_patterns.map((item) => <option key={`pattern-demand-${item}`}>{item}</option>)}</select></label><label>ABC<select value={abcClass} onChange={(event) => change(() => setAbcClass(event.target.value))}><option value="">Tất cả</option>{data?.options.abc_classes.map((item) => <option key={`pattern-abc-${item}`}>{item}</option>)}</select></label><label>Vòng đời<select value={lifecycle} onChange={(event) => change(() => setLifecycle(event.target.value))}><option value="">Tất cả</option>{data?.options.lifecycles.map((item) => <option key={`pattern-lifecycle-${item}`}>{item}</option>)}</select></label>
    </section>
    {error ? <div className="error-banner">{error}</div> : null}
    <section className={`ps-kpis ${loading ? "loading" : ""}`}><article><span>Tổng bộ mẫu</span><strong>{formatNumber(data?.kpis.pattern_count)}</strong><small>Pattern set distinct</small></article><article><span>Demand quantity</span><strong>{formatNumber(data?.kpis.gross_quantity)}</strong><small>Quantity dương sau netting tháng</small></article><article><span>Doanh thu</span><strong>{money(data?.kpis.revenue)}</strong><small>Trong kỳ chọn</small></article><article><span>Active / Inactive</span><strong>{formatNumber(data?.kpis.active_count)} / {formatNumber(data?.kpis.inactive_count)}</strong><small>Trạng thái bộ mẫu</small></article><article><span>Mới trong kỳ</span><strong>{formatNumber(data?.kpis.new_count)}</strong><small className={growthClass(newGrowth)}>{formatPercent(newGrowth)} so kỳ trước</small></article><article className={data?.kpis.inactive_alert_count ? "kpi-alert" : ""}><span>Cảnh báo inactive</span><strong>{formatNumber(data?.kpis.inactive_alert_count)}</strong><small>{formatNumber(data?.kpis.inactive_variant_count)}/{formatNumber(data?.kpis.variant_count)} variant inactive</small></article></section>

    <details className="ps-method"><summary>Phương pháp Demand Pattern, vòng đời và cảnh báo</summary><div><p><b>Demand Pattern</b> — {data?.methodology.pattern_rollup}</p><p><b>Trọng số</b> — {data?.methodology.weight}</p><p><b>Độ phân tán</b> — {data?.methodology.dispersion}</p><p><b>Mới ra mắt</b> — {data?.methodology.lifecycle.new}</p><p><b>Tăng trưởng</b> — {data?.methodology.lifecycle.growth}</p><p><b>Trưởng thành</b> — {data?.methodology.lifecycle.mature}</p><p><b>Suy giảm</b> — {data?.methodology.lifecycle.decline}</p><p><b>Cảnh báo inactive</b> — {data?.methodology.inactive_alert}</p></div></details>

    <section className="ps-grid"><article className="ps-panel"><header><div><p className="eyebrow">SIZE</p><h4>Demand theo kích thước</h4></div></header><div className="ps-bars">{data?.sizes.map((item, index) => { const max = Math.max(...(data?.sizes.map((row) => row.gross_quantity) ?? [1]), 1); return <div key={`size-bar-${item.size_code}-${index}`}><span>{item.size_code}</span><i><b style={{ width: `${item.gross_quantity / max * 100}%` }} /></i><strong>{formatNumber(item.gross_quantity)}</strong><small className={growthClass(item.growth)}>{formatPercent(item.growth)}</small></div>; })}</div></article><article className="ps-panel"><header><div><p className="eyebrow">SIZE × REGION</p><h4>Sở thích kích thước theo vùng</h4></div><div className="metric-toggle">{(["quantity", "revenue", "growth"] as Metric[]).map((metric) => <button key={`matrix-metric-${metric}`} className={matrixMetric === metric ? "selected" : ""} onClick={() => setMatrixMetric(metric)}>{metric}</button>)}</div></header><Matrix rows={data?.size_region ?? []} rowKey="size_code" rowLabel="Kích thước" metric={matrixMetric} /></article></section>
    <article className="ps-panel"><header><div><p className="eyebrow">PATTERN × REGION</p><h4>Pareto/ABC bộ mẫu riêng từng vùng</h4></div><span>Badge A/B/C tính độc lập trong từng vùng · Top 20 theo quantity</span></header><Matrix rows={data?.pattern_region ?? []} rowKey="pattern_set" rowLabel="Bộ mẫu" metric={matrixMetric} /></article>

    <section className="ps-grid"><article className="ps-panel"><header><div><p className="eyebrow">TOP / BOTTOM</p><h4>Ranking bộ mẫu</h4></div><div className="metric-toggle"><button className={rankingMetric === "demand" ? "selected" : ""} onClick={() => setRankingMetric("demand")}>Demand</button><button className={rankingMetric === "growth" ? "selected" : ""} onClick={() => setRankingMetric("growth")}>Growth</button></div></header><div className="ps-ranking"><div><h5>Top 10</h5>{rankingTop?.map((row, index) => <button key={`ranking-top-${row.pattern_set}-${index}`} onClick={() => openDetail(row.pattern_set)}><span>{index + 1}. {row.pattern_set}</span><strong className={rankingMetric === "growth" ? growthClass(row.growth) : ""}>{rankingMetric === "growth" ? formatPercent(row.growth) : formatNumber(row.gross_quantity)}</strong></button>)}</div><div><h5>Bottom 10</h5>{rankingBottom?.map((row, index) => <button key={`ranking-bottom-${row.pattern_set}-${index}`} onClick={() => openDetail(row.pattern_set)}><span>{row.pattern_set}</span><strong className={rankingMetric === "growth" ? growthClass(row.growth) : ""}>{rankingMetric === "growth" ? formatPercent(row.growth) : formatNumber(row.gross_quantity)}</strong></button>)}</div></div></article><article className="ps-panel"><header><div><p className="eyebrow">PARETO</p><h4>Đóng góp tích lũy</h4></div><span>{formatNumber(data?.ranking.pareto_80_count)} bộ mẫu tạo 80% demand</span></header><div className="ps-pareto">{data?.ranking.pareto.slice(0,50).map((row, index) => <i key={`pareto-${row.pattern_set}-${index}`} title={`${row.pattern_set}: ${formatPercent(row.cumulative_pct)}`} style={{ height: `${Math.max(3,(row.contribution_pct ?? 0) * 600)}px` }} />)}</div><p className="ps-note">ABC toàn hệ thống: A đến 80%, B đến 95%, C là long-tail. Ma trận phía trên hiển thị ABC tính lại riêng từng vùng.</p></article></section>

    <article className="ps-panel ps-alerts"><header><div><p className="eyebrow">EXCEPTIONS</p><h4>Bộ mẫu có tỷ lệ variant inactive tăng nhanh</h4></div><span>{data?.methodology.inactive_alert}</span></header>{data?.inactive_alerts.length ? <div className="alert-list">{data.inactive_alerts.map((row, index) => <button key={`inactive-alert-${row.pattern_set}-${index}`} onClick={() => openDetail(row.pattern_set)}><strong>{row.pattern_set}</strong><span>{formatPercent(row.previous_inactive_variant_rate)} → {formatPercent(row.inactive_variant_rate)}</span><b>+{formatPercent(row.inactive_rate_change)}</b></button>)}</div> : <p className="ps-empty">Không có bộ mẫu vượt ngưỡng cảnh báo trong tập đang lọc.</p>}</article>

    <article className="ps-panel"><header><div><p className="eyebrow">PATTERN DETAIL</p><h4>Cấu trúc, demand và vòng đời</h4></div><span>{formatNumber(data?.total)} kết quả</span></header><div className="ps-table-scroll"><table className="ps-table"><thead><tr><th>Pattern set</th><th>Base SKU</th><th>Biến thể active/tổng</th><th>Trạng thái</th><th>Quantity</th><th>Doanh thu</th><th>Trend 12T</th><th>ADI</th><th>CV²</th><th>Demand</th><th>ABC</th><th>Vòng đời</th><th>Độ phủ</th><th>Line count</th><th>Qty/dòng</th><th>Doanh thu/dòng</th><th>First observed</th><th>Last sale</th></tr></thead><tbody>{data?.items.map((row, index) => <tr key={`pattern-row-${row.pattern_set}-${index}`} onClick={() => openDetail(row.pattern_set)}><td><strong>{row.pattern_set}</strong>{(row.inactive_rate_change ?? 0) >= .15 ? <em className="alert-badge">Inactive tăng</em> : null}<small>{row.sku_name}</small></td><td>{row.base_sku_count}</td><td>{row.active_variant_count}/{row.variant_count}<small>{formatPercent(row.inactive_variant_rate)} inactive · Δ {formatPercent(row.inactive_rate_change)}</small></td><td><span className={`status ${activeClass(row.status)}`}>{row.status}</span></td><td className="num">{formatNumber(row.gross_quantity)}</td><td className="num">{money(row.revenue)}</td><td><Sparkline points={row.trend} /></td><td>{number(row.adi)}</td><td>{row.cv === null ? "—" : number(row.cv ** 2)}</td><td><span className={`pattern ${row.demand_pattern.toLowerCase()}`}>{row.demand_pattern}</span></td><td><span className={`abc abc-${row.abc_class.toLowerCase()}`}>{row.abc_class}</span></td><td><span className="lifecycle" title="Tuổi sản phẩm và tăng trưởng trung bình 3 tháng gần nhất so với 3 tháng trước đó">{row.lifecycle}</span></td><td>{row.selling_branch_count} CN</td><td className="num">{formatNumber(row.line_count)}</td><td className="num">{number(row.quantity_per_line)}</td><td className="num">{money(row.revenue_per_line)}</td><td>{formatMonth(row.first_observed_month)}</td><td>{row.last_positive_sale_month ? formatMonth(row.last_positive_sale_month) : "—"}</td></tr>)}</tbody></table></div><footer className="ps-pagination"><button disabled={page<=1||loading} onClick={() => {setLoading(true);setPage((value)=>value-1);}}>← Trước</button><span>Trang {page}/{pages}</span><button disabled={page>=pages||loading} onClick={() => {setLoading(true);setPage((value)=>value+1);}}>Sau →</button></footer></article>

    {detailLoading ? <article className="ps-panel"><p className="ps-empty">Đang tải chi tiết…</p></article> : null}{detail ? <article className="ps-panel ps-detail"><header><div><p className="eyebrow">DRILL-IN · PATTERN TỪNG VARIANT</p><h4>{detail.pattern_set}</h4><small>{formatMonth(detail.filters.date_from)} – {formatMonth(detail.filters.date_to)} · ADI {detail.thresholds.adi} · CV² {detail.thresholds.cv2}</small></div><button onClick={() => setDetail(null)}>Đóng ×</button></header><HistoryChart rows={detail.history} /><section className="ps-grid"><div><h5>Đóng góp và pattern giữa các biến thể</h5><div className="variant-bars">{detail.variants.slice(0,20).map((row, index) => <div key={`variant-bar-${detail.pattern_set}-${row.base_sku}-${row.bravo_sku}-${index}`}><span>{row.factory_sku} · <b className={`pattern ${row.demand_pattern.toLowerCase()}`}>{row.demand_pattern}</b></span><i><b style={{width:`${(row.contribution_pct??0)*100}%`}} /></i><strong>{formatPercent(row.contribution_pct)}</strong></div>)}</div></div><div><h5>Phân bố chi nhánh</h5><div className="distribution">{detail.distribution.slice(0,20).map((row, index) => <div key={`distribution-${detail.pattern_set}-${row.region}-${row.branch_code}-${index}`}><span>{row.branch_code} · {row.region}</span><strong>{formatNumber(row.gross_quantity)}</strong></div>)}</div></div></section><div className="ps-table-scroll"><table className="ps-table variants"><thead><tr><th>Bravo SKU</th><th>Base SKU</th><th>Factory SKU</th><th>Loại</th><th>Demand pattern</th><th>ADI</th><th>CV²</th><th>Lịch sử / tháng bán</th><th>Tháng net âm</th><th>Quantity</th><th>Đóng góp</th><th>First observed</th><th>Last sale</th><th>Trạng thái</th></tr></thead><tbody>{detail.variants.map((row, index) => <tr key={`variant-row-${detail.pattern_set}-${row.base_sku}-${row.bravo_sku}-${index}`}><td><strong>{row.bravo_sku}</strong><small>{row.sku_name}</small></td><td>{row.base_sku}</td><td>{row.factory_sku}</td><td>{row.variant_type}</td><td><span className={`pattern ${row.demand_pattern.toLowerCase()}`}>{row.demand_pattern}</span></td><td>{number(row.adi)}</td><td>{number(row.cv2)}</td><td>{formatNumber(row.history_months)} / {formatNumber(row.positive_months)}</td><td className={row.negative_months ? "negative" : "neutral"}>{formatNumber(row.negative_months)}</td><td>{formatNumber(row.gross_quantity)}</td><td>{formatPercent(row.contribution_pct)}</td><td>{formatMonth(row.first_observed_month)}</td><td>{row.last_positive_sale_month?formatMonth(row.last_positive_sale_month):"—"}</td><td><span className={`status ${activeClass(row.status)}`}>{row.status}</span></td></tr>)}</tbody></table></div></article> : null}
    <p className="ps-note">Một pattern_set có thể chứa nhiều base SKU và mỗi Bravo SKU được phân loại riêng. Pattern dùng ADI {data?.thresholds.adi ?? "—"}, CV² {data?.thresholds.cv2 ?? "—"}, tối thiểu {data?.thresholds.min_history_months ?? "—"} tháng lịch sử và {data?.thresholds.min_positive_months ?? "—"} tháng bán.</p><style jsx>{styles}</style>
  </div>;
}

